// Synthetic decision cases; expected prose is independent of the renderer.
const balance = 'Want me to show your account balances?';
const history = 'Your account ending 1234 has records from January 2024 through October, last updated October 12 at 12:00 PM.';
const spend = 'How much did I spend at Store One in October 2026?';
const extraAccount = (f, status = 'complete') => {
  f.raw("INSERT INTO fin_accounts (account_slug,entity_slug,account_kind,balance_role,mask,feed_mode,provenance,basis_state,recorded_at) VALUES ('reserve','owner','savings','asset','5678','manual','owner_stated','confirmed','2026-10-12')");
  f.raw("INSERT INTO fin_account_coverage (account_slug,coverage_status,covered_from,covered_to,computed_at,provenance,basis_state,recorded_at) VALUES ('reserve',?,'2026-10-01','2026-10-31','2026-10-12','owner_stated','confirmed','2026-10-12')", status);
  f.raw("INSERT INTO fin_balance_snapshots (account_slug,as_of_date,current_minor,provenance,basis_state,recorded_at) VALUES ('reserve','2026-10-12',7000,'owner_stated','confirmed','2026-10-12')");
};
export const cases = [
  { id: 'wording', question: 'What is my average spending?', reason: 'ledger_wording_unsupported',
    expected: `I want to make sure I get this right. I can show you balances, recent transactions, or what you spent in a set period. Which would help most?` },
  { id: 'timezone', question: 'What are my expenses this month?', reason: 'owner_timezone_unavailable',
    setup: f => { f.env.BRAIN_TIMEZONE = 'Invalid/Zone'; }, repair: 'Set your time zone',
    expected: `I can check a month and year, but relative dates need a valid time zone.\nWant to choose a month and year?` },
  { id: 'cash-flow', question: 'What was my cash flow in October 2026?', reason: 'cash_flow_unsupported',
    expected: `Cash flow gets tricky here, since some card purchases may not be paid yet. I can show money in and money out side by side instead. Want that?` },
  { id: 'hidden-merchant', question: 'How much did I spend at unknown merchant in October 2026?', reason: 'merchant_selector_unsupported',
    expected: `That store's name is hidden, shortened, or unknown on your statement, so I do not want to guess. If you tell me roughly what it was, I'll look again.` },
  { id: 'conjunction', question: 'How much did I spend at Store and Supply in October 2026?', reason: 'merchant_selector_ambiguous',
    setup: f => f.add('conjunction', 'Store & Supply', 'Store & Supply', { direction: 'outflow' }),
    expected: `A different spelling with "and" or "&" may be a different business, so those names stay separate.\n${balance}` },
  { id: 'import-review', question: spend, reason: 'coverage_review_required', repair: 'Ask the installer to check the bank statements',
    setup: f => f.raw("UPDATE fin_account_coverage SET basis_note='Read from a bank export covering uncertain days'"),
    expected: `I can help review the bank records, but an earlier import may have left gaps between dates, so a complete total is unconfirmed.\n${history}\nWant help checking the bank statements?` },
  { id: 'export-overlap', question: spend, reason: 'bank_export_overlap_review_required', repair: 'Ask the installer to compare the original statements',
    setup: f => { for (const external of [null, 'receipt-unit']) f.raw("INSERT INTO fin_transactions (txn_uid,account_slug,posted_on,amount_minor,direction,payee,external_id,source_doc_uid,provenance,basis_state,recorded_at) VALUES (?,'fixture-account','2026-10-05',2500,'outflow','Store One',?,'synthetic-export','extracted','confirmed','2026-10-12')", 'export-'+String(external), external); },
    expected: `I can help compare the bank records, but two exports may count the same purchase twice, so a reliable total is unconfirmed.\n${history}\nWant help comparing the original statements?` },
  { id: 'no-accounts', question: spend, reason: 'no_accounts', repair: 'Connect the bank account',
    setup: f => f.raw("UPDATE fin_entities SET relationship='counterparty'"),
    expected: `I can help find the right account, but no connected account matches this request.\nWant help connecting the account you want to ask about?` },
  { id: 'ambiguous-account', question: spend, reason: 'ambiguous_account', repair: 'Ask the installer to confirm',
    setup: f => f.raw("UPDATE fin_accounts SET basis_state='proposed'"),
    expected: `I can help choose the right account, but its details are still unconfirmed.\n${history}\nWant help confirming which account to use?` },
  { id: 'currency', question: spend, reason: 'unsupported_currency', repair: 'Connect a US dollar account',
    setup: f => f.raw("UPDATE fin_accounts SET currency='EUR'"),
    expected: `I can help review a US dollar account separately, but at least one of these accounts uses another currency, so a combined US dollar total is unconfirmed.\n${history}\nWant to choose a US dollar account?` },
  { id: 'period', question: 'How much did I spend at Store One in September 2023?', reason: 'period_outside_coverage',
    expected: `I can help check the bank records for September 2023, but some bank days are missing, so a complete answer is unconfirmed.\n${history}\n${balance}` },
  { id: 'not-synced', question: spend, reason: 'period_outside_coverage',
    setup: f => f.raw("UPDATE fin_account_coverage SET coverage_status='partial'"),
    expected: `I can help check the bank records for October, but some bank days are missing, so a complete answer is unconfirmed.\n${history}\n${balance}` },
  { id: 'unreadable', question: spend, reason: 'unreadable_transactions',
    setup: f => f.raw("UPDATE fin_transactions SET basis_state='proposed'"),
    expected: `I can help review these transactions, but some amounts, dates, currencies, or directions are unconfirmed, so no total is confirmed.\n${history}\n${balance}` },
  { id: 'balance-missing', question: 'What are my account balances?', reason: 'balance_unavailable', repair: 'Refresh the bank connection',
    setup: f => f.raw('DELETE FROM fin_balance_snapshots'),
    expected: `I can help review the bank connection, but a confirmed US dollar balance dated on or before today is missing or unreadable, so not every balance is available.\n${history}\nWant help refreshing the bank connection?` },
  { id: 'read-failed', question: spend, reason: 'ledger_unavailable', repair: 'Ask the installer to check the bank connection',
    setup: f => { f.env.DB.batch = async () => { f.calls.push('injected failed read'); throw new Error('synthetic read failure'); }; },
    expected: `I can help check the bank connection, but the bank data was not read successfully or exceeded the account or transaction limit.\n${history}\nWant help checking the connection before trying again?` },
  { id: 'restricted', question: spend, reason: 'retrieval_scope_restricted', options: { grantScope: { all: false } }, repair: 'Use your owner session',
    expected: `I can help with the records this session permits, but limited access or document filters keep bank accounts out of this answer.\nWant to use your owner session without document filters?` },
  { id: 'unsupported', question: spend, reason: 'unsupported_question', options: { ledgerEligible: false }, repair: 'Connect the records',
    expected: `I can help review your completed bank transactions, but they do not establish this fact on their own.\nWant help finding records that establish it?` },
  { id: 'vendor-possible', question: 'How much did I spend at Store Missing in October 2026?',
    setup: f => f.add('possible', 'Store Missing charge', null, { direction: 'outflow' }),
    expected: `I found 1 transaction mentioning "Store Missing", but the bank did not name it as the payee, so no store total is confirmed.\n${balance}` },
  { id: 'vendor-absent', question: 'How much did I spend at Store Missing in October 2026?',
    expected: `I checked October, but no payee exactly matched "Store Missing", so no store total is confirmed. Closest payee names: Store One.\nWant me to check spending at Store One in October?` },
  { id: 'vendor-mixed', question: spend,
    setup: f => f.add('possible', 'Store One charge', null, { direction: 'outflow', cents: 1200 }),
    expected: `Here is a partial view for "Store One": the bank names it on charges totaling $25.00; another $12.00 only mentions it in the transaction text. These amounts stay separate, with no complete store total confirmed [1].\n${balance}` },
  { id: 'expense-unknown', contextExpected: 'Money out I could check: $25.00 in October.\nPeriod: October.', question: 'What were my expenses in October 2026?',
    setup: f => f.raw("UPDATE fin_accounts SET account_kind='other',balance_role='neither'"),
    expected: `Here is the money out I could check, with spending still unconfirmed. The account types for your account ending 1234 have not been confirmed, so some payments may be between your own accounts.\n${balance}` },
  { id: 'payment-payer', question: 'Did the payment from Payer Missing arrive in October 2026?',
    setup: f => f.add('inflow', 'unidentified receipt', null),
    expected: `I found 1 deposit, but the bank details do not identify it as that payer's payment, so payment is unconfirmed.\n${balance}` },
  { id: 'payment-many', question: 'Did a payment of $25.00 arrive around October 5, 2026?',
    setup: f => { f.add('inflow-one', 'receipt one', 'Payer One'); f.add('inflow-two', 'receipt two', 'Payer Two'); },
    expected: `I found 2 matching deposits in September 28 to October 12, so no single payment is confirmed.\n${balance}` },
  { id: 'forecast', question: 'What will my bank balance be next month?',
    expected: `I can show your recorded balances, but future balances and payments are unknown.\n${balance}` },
  { id: 'forecast-missing', question: 'What will my bank balance be next month?', reason: 'balance_unavailable', repair: 'Refresh the bank connection',
    setup: f => f.raw('DELETE FROM fin_balance_snapshots'),
    expected: `I can help review your records, but future balances and payments are unknown. I can help review the bank connection, but a confirmed US dollar balance dated on or before today is missing or unreadable, so not every balance is available.\n${history}\nWant help refreshing the bank connection?` },
  { id: 'transactions-short', question: 'Show my last ten transactions.',
    expected: `I found 1 completed transaction; this is a partial list that may not include your latest 10 transactions because the saved bank history may be incomplete.\n${balance}` },
  { id: 'pending', question: spend,
    expected: `This reading covers completed transactions only; pending activity is not included.\n${balance}` },
  { id: 'documents', question: 'What is my average spending?', reason: 'ledger_wording_unsupported', documentAnswer: 'A dated document answer.',
    expected: "This answer comes from your documents; I did not match it to your bank data." },
  { id: 'account-link', question: spend, reason: 'ledger_account_link_required', repair: 'Ask the installer to review',
    setup: f => f.raw("INSERT INTO fin_accounts (account_slug,entity_slug,account_kind,balance_role,mask,feed_mode,provenance,basis_state,recorded_at) VALUES ('manual-copy','owner','checking','asset','1234','manual','owner_stated','confirmed','2026-10-12')"),
    expected: `I can help review these records, but an import and a bank connection may describe the same account, so they stay separate: your account ending 1234.\nWant help reviewing them together?` },
  { id: 'expense-partial', contextExpected: 'Spending I could check: $25.00 in October (some accounts missing dates).\nPeriod: October.', question: 'What were my expenses in October 2026?',
    setup: f => extraAccount(f, 'partial'),
    expected: `Here is a partial view using 1 of 2 accounts for October; your account ending 5678 is missing some dates.\n${balance}` },
  { id: 'vendor-partial', question: spend, setup: f => extraAccount(f, 'partial'),
    expected: `Here is a partial subtotal for "Store One": the charges I can use total $25.00 in October; 1 account is missing some dates: your account ending 5678 [1].\n${balance}` },
  { id: 'ranking-partial', question: 'What were my five biggest expenses in October 2026?',
    setup: f => {
      const slug = 'simplefin-' + 'a'.repeat(16);
      for (const table of ['fin_accounts','fin_account_coverage','fin_transactions','fin_balance_snapshots']) f.raw(`UPDATE ${table} SET account_slug=?`, slug);
      f.raw("UPDATE fin_accounts SET account_kind='other',balance_role='neither'");
      f.raw("UPDATE fin_account_coverage SET coverage_status='partial'");
    },
    expected: `Here are the expenses I found in a partial ranking; the bank connection has not supplied every day in the requested period.\n${balance}` },
  { id: 'income-payer', question: 'How much income came from Payer Missing in October 2026?',
    setup: f => f.add('payer-receipt', 'unidentified receipt', null),
    expected: `I can help review the deposits, but the full income from that payer is unconfirmed. There is 1 deposit, and its bank label may not identify who paid.\n${balance}` },
  { id: 'income-labels', question: 'Show income by merchant in October 2026?',
    setup: f => f.add('payer-receipt', 'receipt', 'Payer One'),
    expected: `Bank payee names may not identify who paid, so the sender of every deposit is still unconfirmed.\n${balance}` },
  { id: 'inflow-income', question: 'How much money came in in October 2026?',
    setup: f => f.add('payer-receipt', 'receipt', 'Payer One'),
    expected: `Income is still unconfirmed; a deposit can be a transfer or another kind of credit, and the bank label alone does not prove its source.\n${balance}` },
  { id: 'transfers', question: 'Show my own-account transfers in October 2026?',
    expected: `This reading checks possible moves with enough account details to review; matching amounts alone do not confirm transfers, and no matches does not prove none occurred.\n${balance}` },
  { id: 'recurring', question: 'Show my recurring charges in October 2026?',
    expected: `I can show repeated bank charges as possible patterns, but they do not prove an active subscription; no detected pattern does not prove none exists.\n${balance}` },
  { id: 'payment-absent', question: 'Did a payment of $25.00 arrive in October 2026?',
    expected: `I checked the dates and accounts shown and found no matching completed deposit; payment outside those dates and accounts remains unconfirmed.\n${balance}` },
  { id: 'transactions-empty', question: 'Show my last ten transactions.', setup: f => f.raw('DELETE FROM fin_transactions'),
    expected: `I found 0 completed transactions; this is a partial list that may not include your latest 10 transactions because the saved bank history may be incomplete.\n${balance}` },
  { id: 'income-at-least', question: 'How much income came from Payer One in October 2026?',
    setup: f => { f.add('named-receipt', 'receipt', 'Payer One'); f.add('other-receipt', 'receipt', 'Payer Two'); },
    expected: `Income from that payer is at least $25.00 (matched subtotal, not complete); I can help review the deposits, but the full income from that payer is unconfirmed. There are 2 deposits, and their bank labels may not identify who paid.\n${balance} [1]` },
  { id: 'balance-live', question: 'What are my account balances?', repair: 'Refresh the bank connection',
    expected: "Here are your recorded balances, with the date for each account; these do not show live or available cash.\nWant help refreshing the bank connection for a newer balance?" },
  { id: 'ranking-empty', question: 'What were my five biggest expenses in October 2026?',
    setup: f => {
      const slug = 'simplefin-' + 'a'.repeat(16);
      for (const table of ['fin_accounts','fin_account_coverage','fin_balance_snapshots']) f.raw(`UPDATE ${table} SET account_slug=?`, slug);
      f.raw('DELETE FROM fin_transactions');
      f.raw("UPDATE fin_accounts SET account_kind='other',balance_role='neither'");
      f.raw("UPDATE fin_account_coverage SET coverage_status='partial'");
    },
    expected: `I checked the saved transactions and found no matches, but some days may be missing, so this is a partial ranking and does not confirm there were no expenses.\n${balance}` },
  { id: 'vendor-quoted-label', question: 'How much did I spend at Store Missing in October 2026?',
    setup: f => f.raw("UPDATE fin_transactions SET payee=?", 'Store "Q"'),
    expected: `I checked October, but no payee exactly matched "Store Missing", so no store total is confirmed. Closest payee names: Store "Q".\n${balance}` },
  { id: 'vendor-owned-only', question: 'How much did I spend at Store Missing in October 2026?',
    setup: f => {
      extraAccount(f); f.raw('DELETE FROM fin_transactions');
      f.add('owned-out', 'TRANSFER TO account 5678', 'Transfer', { direction: 'outflow' });
      f.raw("INSERT INTO fin_transactions (txn_uid,account_slug,posted_on,amount_minor,direction,description,payee,provenance,basis_state,recorded_at) VALUES ('owned-in','reserve','2026-10-05',2500,'inflow','TRANSFER FROM account 1234',NULL,'owner_stated','confirmed','2026-10-12')");
    },
    expected: `I checked October, but no payee exactly matched "Store Missing", so no store total is confirmed. Closest payee names: Transfer.\n${balance}` },
  { id: 'category-unconfirmed', question: 'Show my spending by category in October 2026?',
    setup: f => f.raw("UPDATE fin_transactions SET category='Supplies',category_basis_state='proposed'"),
    expected: `Here are the spending categories from your bank; those marked unconfirmed have not been reviewed.\n${balance}` },
  { id: 'partial-history-gap', question: 'Show my last ten transactions.', reason: 'ledger_partial_coverage',
    expected: `This is a partial reading of the bank records; some days may be missing, so the list or ranking may be incomplete.\n${history}\n${balance}` },
];
